:- set_prolog_flag(iso, true).
- test(lgt_open_4_40, true(Reposition == false), [note('implementation defined per ISO standard')]) :-
		{open(rf, write, Stream, [reposition(true), reposition(false)]),
		 stream_property(Stream, reposition(Reposition))}.
cleanup :- lgt_h(lgt_clean_file(roger_data)),
		lgt_h(lgt_clean_file(scowen)),
		lgt_h(lgt_clean_file(dave)),
		lgt_h(lgt_clean_file(foo)),
		lgt_h(lgt_clean_file(bar)),
		lgt_h(lgt_clean_file(f)),
		lgt_h(lgt_clean_file(no_read_permission)),
		lgt_h(lgt_clean_file(no_write_permission)),
		lgt_h(lgt_clean_file(no_append_permission)),
		lgt_h(lgt_clean_file(d1)),
		lgt_h(lgt_clean_file(d2)),
		lgt_h(lgt_clean_file(tt)),
		lgt_h(lgt_clean_file(tb)),
		lgt_h(lgt_clean_file(rt)),
		lgt_h(lgt_clean_file(rf)).
create_no_read_permission_file :-
		lgt_os_operating_system_type(unix),
		not_running_as_root,
		lgt_h(lgt_file_path('no_read_permission', Path)),
		lgt_h(lgt_create_text_file(Path, 'foo.')),
		atom_concat('chmod a-r ', Path, Command),
		lgt_os_shell(Command).
create_no_write_permission_file :-
		lgt_os_operating_system_type(unix),
		not_running_as_root,
		lgt_h(lgt_file_path('no_write_permission', Path)),
		lgt_h(lgt_create_text_file(Path, 'foo.')),
		atom_concat('chmod a-w ', Path, Command),
		lgt_os_shell(Command).
create_no_append_permission_file :-
		lgt_os_operating_system_type(unix),
		not_running_as_root,
		lgt_h(lgt_file_path('no_append_permission', Path)),
		lgt_h(lgt_create_text_file(Path, 'foo.')),
		atom_concat('chmod a-w ', Path, Command),
		lgt_os_shell(Command).
not_running_as_root :-
		lgt_os_operating_system_type(unix),
		lgt_os_shell('if [ "$(id -u)" -eq 0 ]; then exit 1; fi').
'$lgt_say'(V) :- write(user_output, '@V '), write(user_output, V), nl(user_output).
'$lgt_say2'(V, B) :- write(user_output, '@V '), write(user_output, V), write(user_output, ' | '), catch(writeq(user_output, B), _, write(user_output, '<unprintable>')), nl(user_output).
'$lgt_want'('$lgt_no_ball_expected_here').
'$lgt_want'(error(domain_error(source_sink,foo(1,2)), _)).
'$lgt_cond' :- true.
'$lgt_case' :- (open(foo(1,2), write, _)), ignore(catch(cleanup, _, true)).
'$lgt_run' :- catch( ( catch('$lgt_cond', _, fail) -> catch( ( '$lgt_case' -> '$lgt_say'(succ) ; '$lgt_say'(fail) ), B, ( B = '$lgt_harness'(_) -> '$lgt_say2'(harness, B) ; '$lgt_want'(B) -> '$lgt_say'(ballmatch) ; '$lgt_say2'(ballother, B) ) ) ; '$lgt_say'(skipped) ), B2, '$lgt_say2'(toplevel, B2) ).
:- initialization('$lgt_run').
