:- set_prolog_flag(iso, true).
:- multifile(portray/1).
:- dynamic(portray/1).
portray(Atom) :-
	atom(Atom),
	write(Atom),
	write(Atom).
portray(Float) :-
	float(Float),
	Integer is truncate(Float),
	write(Integer).
cleanup :- lgt_h(lgt_clean_binary_output),
		lgt_h(lgt_clean_text_output),
		lgt_h(lgt_clean_text_input).
max_depth_option_supported :-
		current_logtalk_flag(prolog_dialect, Dialect),
		Dialect \== b, Dialect \== cx, Dialect \== ji.
portrayed_option_supported :-
		current_logtalk_flag(prolog_dialect, Dialect),
		Dialect \== b, Dialect \== cx, Dialect \== ji, Dialect \== tau, Dialect \== yap.
'$lgt_say'(V) :- write(user_output, '@V '), write(user_output, V), nl(user_output).
'$lgt_say2'(V, B) :- write(user_output, '@V '), write(user_output, V), write(user_output, ' | '), catch(writeq(user_output, B), _, write(user_output, '<unprintable>')), nl(user_output).
'$lgt_want'('$lgt_no_ball_expected_here').
'$lgt_cond' :- true.
'$lgt_case' :- lgt_h(lgt_set_text_output('')),
		(writeq(+(1))),
		lgt_h(lgt_text_output_assertion('+1', Assertion)), (Assertion), ignore(catch(cleanup, _, true)).
'$lgt_run' :- catch( ( catch('$lgt_cond', _, fail) -> catch( ( '$lgt_case' -> '$lgt_say'(succ) ; '$lgt_say'(fail) ), B, ( B = '$lgt_harness'(_) -> '$lgt_say2'(harness, B) ; '$lgt_want'(B) -> '$lgt_say'(ballmatch) ; '$lgt_say2'(ballother, B) ) ) ; '$lgt_say'(skipped) ), B2, '$lgt_say2'(toplevel, B2) ).
:- initialization('$lgt_run').
